// Üretilen dosya: tool/ozgun/uret.py. Mühendislik ve Tasarım · Genel ek sorular: Mühendislik ve Tasarım kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: İnşaat ve yapı mühendisliği temel kavramları, ünlü yapılar | Makine, otomotiv ve havacılık temel kavramları | Elektrik-elektronik mühendisliği temel kavramları ve devre elemanları | Tasarım süreci, malzeme bilgisi, ölçme ve mühendislik etiği) (orta).
const ozEngineering5Orta = <(String, String, List<String>, String)>[
  ('TIG kaynağında kullanılan tungsten elektrot için hangisi doğrudur?', 'Arkı oluşturur ama erimez; dolgu teli ayrıca verilir', ['Eriyerek dikişin dolgu metalini oluşturur', 'Eriyip yanarak koruyucu gazı kendisi üretir', 'Yalnız kaynak bittikten sonra dikişteki cürufu kazıyıp temizlemekte kullanılır'], 'TIG (tungsten inert gaz) kaynağında tungstenin çok yüksek ergime sıcaklığı sayesinde elektrot tüketilmez; gerekirse dolgu çubuğu elle ayrıca beslenir.'),
  ('Sürekli beslenen tel elektrotla yapılan gazaltı kaynağında MIG ile MAG arasındaki temel fark nedir?', 'Koruyucu gazın soy (inert) ya da aktif olması', ['Elektrodun tungstenden mi yoksa saf bakırdan mı yapıldığı', 'Akımın doğru ya da alternatif olması', 'Kaynağın elle ya da robotla yapılması'], 'MIG\'de argon, helyum gibi soy gazlar; MAG\'da ise karbondioksit içeren aktif gazlar kullanılır. Tel besleme ilkesi ikisinde de aynıdır.'),
  ('Elle yapılan örtülü elektrot (çubuk) kaynağında elektrodun dışındaki örtünün başlıca görevi nedir?', 'Eriyerek koruyucu gaz ve cüruf oluşturmak', ['Elektrodu elektrik çarpmasına karşı yalıtmak', 'Elektrodun paslanmasını önleyip ömrünü uzatmak', 'Arkın sıcaklığını düşürüp sıçramayı artırmak'], 'Örtü yanıp eridiğinde erimiş banyoyu havadaki oksijen ve azottan koruyan bir gaz bulutu ve üstünü örten cüruf tabakası oluşturur.'),
  ('Kaynak dikişinin hemen yanında, erimediği hâlde ısının etkisiyle iç yapısı ve özellikleri değişen bölgeye ne ad verilir?', 'Isı tesiri altındaki bölge', ['Kaynak ağzı', 'Cüruf katmanı', 'Cüruf ve koruyucu gaz katmanı'], 'Isı tesiri altındaki bölgede (ITAB) tane büyümesi ya da sertleşme gibi değişimler olur ve kaynaklı birleşimlerde çatlaklar sıklıkla bu bölgede başlar.'),
  ('T biçiminde birleştirilen iki levhanın arasındaki iç köşeye üçgen kesitli olarak çekilen dikiş türü hangisidir?', 'Köşe kaynağı', ['Alın kaynağı', 'Punta kaynağı', 'Dikiş (makaralı) kaynağı'], 'Köşe kaynağı birbirine dik ya da açılı duran parçaların oluşturduğu köşeye yapılır; alın kaynağı ise uç uca getirilen parçaların kenarları arasında yapılır.'),
  ('Kum kalıba dökümün kalıcı metal kalıba dökümden temel farkı hangisidir?', 'Kalıp her dökümden sonra parça çıkarılırken bozulur', ['Yalnız plastik ve kauçuk malzemelerin dökümüne uygun bir yöntemdir', 'Erimiş metal kalıba yüksek basınçla basılır', 'Kalıp binlerce döküm için kullanılabilir'], 'Kum kalıp tek kullanımlıktır; parça çıkarılırken kalıp kırılır, kum yeniden hazırlanır. Bu yüzden büyük ve az adetli parçalar için ekonomiktir.'),
  ('Otomobil vites kutusu gövdesi gibi ince cidarlı alüminyum parçaların çok yüksek adetlerde üretimi için erimiş metalin çelik kalıba yüksek basınçla basıldığı yöntem hangisidir?', 'Basınçlı döküm', ['Kum kalıba döküm', 'Kayıp köpük döküm', 'Serbest dövme'], 'Basınçlı dökümde kalıp çelikten yapılır ve tekrar tekrar kullanılır; yüksek basınç ince kesitlerin dolmasını sağlar. Kalıp pahalı olduğundan yöntem seri üretimde kârlıdır.'),
  ('Dökme demir su boruları ve motor silindir gömlekleri gibi içi boş silindirik parçalar hangi döküm yöntemiyle, maça kullanmadan üretilebilir?', 'Savurma (merkezkaç) döküm', ['Hassas döküm', 'Kum kalıba yatay döküm', 'Basınçlı (pres) döküm'], 'Hızla dönen kalıba dökülen metal merkezkaç etkisiyle kalıp duvarına yapışarak katılaşır; ortada kendiliğinden bir boşluk kalır ve yoğun, temiz bir yapı oluşur.'),
  ('Tel çekme işlemi ekstrüzyondan hangi yönüyle ayrılır?', 'Malzeme kalıptan itilmez, çekilerek geçirilir', ['Malzeme her zaman erimiş hâlde kalıba verilir', 'Kalıp kullanılmaz, malzeme merdaneler arasında ezilir', 'Yalnız plastik malzemelere uygulanabilir'], 'Tel çekmede çubuk ya da tel, giderek daralan kalıplardan çekilerek çapı küçültülür; ekstrüzyonda ise kuvvet malzemeyi arkadan iterek kalıptan çıkarır.'),
  ('Metal tozlarının kalıpta preslenip ergime sıcaklığının altında ısıtılarak tanelerin birbirine kaynaştırılması işlemine ne ad verilir?', 'Sinterleme', ['Dövme', 'Normalizasyon', 'Kalsinasyon'], 'Toz metalürjisinde preslenen ham parça sinterleme fırınında ısıtılır; taneler arasında atom difüzyonuyla bağ oluşur ve parça dayanım kazanır.'),
  ('Bir dökümhanede ahşap modelin, dökülecek parçanın çizimdeki ölçülerinden biraz büyük yapılmasının nedeni nedir?', 'Metalin soğurken büzülmesini karşılamak', ['Kalıp kumunun ıslanınca genişlemesini dengelemek', 'Parçayı daha ağır gösterip maliyeti artırmak', 'Erimiş metalin kalıba daha yavaş dolmasını sağlamak'], 'Metal katılaşıp oda sıcaklığına soğurken boyutları küçülür; modele bu yüzden metal türüne göre seçilen bir çekme payı eklenir.'),
  ('Bükülen bir sac parça kalıptan çıkarıldığında büküm açısı bir miktar açılıyor. Bu olayın nedeni ve tasarımda alınan önlem hangisidir?', 'Elastik geri esneme; sac istenenden biraz fazla bükülür', ['Plastik akma; sac ısıtılıp hemen suda hızla soğutulur', 'Sünme; parça uzun süre kalıpta bekletilir', 'Yorulma; büküm sayısı artırılır'], 'Bükmede şekil değiştirmenin bir kısmı elastiktir ve yük kalkınca geri döner. Bu geri esnemeyi karşılamak için kalıp açısı hedef açıdan biraz fazla seçilir.'),
  ('Metallerin sıcak şekillendirmesini soğuk şekillendirmesinden ayıran ölçüt hangisidir?', 'İşlemin yeniden kristalleşme sıcaklığının üstünde yapılması', ['İşlem sırasında metalin tamamen erimesi', 'Uygulanan kuvvetin büyüklüğü', 'Kalıbın önceden soğutulmuş olması'], 'Yeniden kristalleşme sıcaklığının üstünde şekillendirilen metal pekleşmez ve büyük şekil değişimine izin verir; altında yapılan soğuk şekillendirme ise dayanımı artırır ama sünekliği azaltır.'),
  ('Konutlardaki kombilerde ve süt soğutma tesislerinde ince oluklu metal levhalardan oluşan plakalı ısı değiştiricilerin tercih edilme nedeni nedir?', 'Küçük hacimde çok büyük ısı aktarım yüzeyi sağlamaları', ['Akışkanların birbirine karışmasına izin vererek ısıyı doğrudan aktarmaları', 'Hiç bakım ve temizlik gerektirmemeleri', 'Yalnız gazlarla çalışabilmeleri'], 'Plakalar arasında oluşan çok sayıda ince kanal büyük yüzey alanı ve türbülanslı akış yaratır; bu da sıkışık bir hacimde yüksek ısı aktarımı demektir.'),
  ('Sert suyla çalışan bir ısı değiştiricinin borularında zamanla kireç tabakası birikiyor. Bunun cihazın çalışmasına etkisi ne olur?', 'Ek ısıl direnç oluşur ve aktarılan ısı azalır', ['Boruların ısıl iletkenliği artar ve verim yükselir', 'Akışkanların sıcaklık farkı kendiliğinden büyür', 'Kireç pası önlediği için ömür uzar'], 'Kireç ısıyı metalden çok daha kötü iletir; borunun üzerine eklenen bu katman ısı geçişini yavaşlatır, akış kesitini daraltır ve pompa yükünü artırır.'),
  ('Termik santrallerde kullanılan ıslak soğutma kuleleri kondenserden gelen ılık suyu temelde hangi yolla soğutur?', 'Suyun bir kısmının havaya buharlaşmasıyla', ['Suya buz kalıpları eklenmesiyle', 'Suyun yer altındaki borularda dolaştırılmasıyla', 'Suyun soğutucu gazla karıştırılmasıyla'], 'Kulede yukarıdan dökülen su yükselen havayla karşılaşır; buharlaşan küçük miktardaki su gizli ısı olarak büyük bir ısıyı alır ve geri kalan su soğur.'),
  ('Yoğuşmalı kombilerin klasik kombilere göre daha verimli olmasının nedeni nedir?', 'Baca gazındaki su buharını yoğuşturup gizli ısısını geri kazanmaları', ['Doğal gaz yerine elektrikle çalışmaları', 'Suyu kaynama noktasının üstüne çıkarmaları', 'Baca gazını klasik kombilerden çok daha sıcak olarak dışarı atmaları'], 'Doğal gazın yanmasıyla su buharı oluşur. Yoğuşmalı cihazda baca gazı dönüş suyuyla soğutulur; buhar yoğuşurken bıraktığı gizli ısı tesisata kazandırılır.'),
  ('Bir ısı değiştiricide saniyede 2 kg su 20 °C\'den 50 °C\'ye ısıtılıyor. Suyun özgül ısısı 4,18 kJ/(kg·K) alınırsa suya aktarılan ısı gücü yaklaşık kaç kilowattır?', '251 kW', ['125,4 kW', '84 kW', '418 kW'], 'Q = ṁ·c·ΔT = 2 × 4,18 × 30 ≈ 250,8 kW bulunur.'),
  ('Bir yük gemisi nehir ağzındaki tatlı sudan açık denize çıkıyor. Yükü değişmediğine göre geminin sudaki konumu nasıl değişir?', 'Biraz yükselir, su çekimi azalır', ['Biraz daha batar, su çekimi artar', 'Hiç değişmez', 'Önce batar, sonra eski hâline döner'], 'Deniz suyunun yoğunluğu tatlı sudan büyüktür; aynı ağırlığı taşımak için daha az hacimde su yer değiştirmek yeterli olur, bu yüzden gemi yükselir.'),
  ('Bir gemi yüzerken 5000 m³ deniz suyunu yerinden ediyor. Deniz suyunun yoğunluğu 1025 kg/m³ ise geminin toplam kütlesi kaç tondur?', '5125 ton', ['51 250 ton', '5000 ton', '5250 ton'], 'Yüzen geminin kütlesi yer değiştirdiği suyun kütlesine eşittir: 5000 × 1025 = 5 125 000 kg, yani 5125 ton.'),
  ('Boş seyreden dev yük gemilerinin balast tanklarına deniz suyu almasının amacı nedir?', 'Gemiyi yeterince batırıp kararlılığını ve pervane verimini sağlamak', ['Yolcular ve mürettebat için uzun yolculuk boyunca içme suyu depolamak', 'Motorları soğutacak suyu taşımak', 'Yakıt tüketimini sıfıra indirmek'], 'Yükü olmayan gemi çok yüksekte yüzer; rüzgâr etkisi büyür, pervane sudan çıkabilir. Balast suyu ağırlık merkezini alçaltıp gemiyi dengeler.'),
  ('Petrol tankerlerinde çift cidarlı (çift gövdeli) yapının zorunlu hâle getirilmesinin başlıca amacı nedir?', 'Çarpışma ya da karaya oturmada petrolün denize sızmasını önlemek', ['Tankerin hızını artırmak', 'Yükleme süresini kısaltmak', 'Tankerin daha az mürettebatla işletilebilmesi'], 'İki gövde arasındaki boşluk, dış cidar yırtılsa bile iç tankın sağlam kalmasını sağlar. Bu kural 1989 Exxon Valdez kazası gibi büyük sızıntıların ardından yaygınlaştı.'),
  ('Pek çok büyük geminin pruvasında su hattının altında bulunan soğan biçimli çıkıntının işlevi nedir?', 'Gövdenin oluşturduğu dalga direncini azaltmak', ['Buz kırmak için ağırlık eklemek', 'Demiri taşıyıp saklamak', 'Pervaneyi kıyıdaki çarpmalara karşı korumak'], 'Bu çıkıntı kendi dalgasını oluşturur; bu dalga gövde dalgasıyla girişim yaparak onu kısmen söndürür ve belirli hızlarda yakıt tüketimini düşürür.'),
  ('Hızlı yolcu teknelerinde gövdenin altına yerleştirilen su altı kanatlarının (hidrofoil) işlevi nedir?', 'Hız arttıkça gövdeyi sudan kaldırıp sürtünmeyi azaltmak', ['Teknenin daha derine batmasını sağlayıp dalgalarda yalpalamasını engellemek', 'Dalga yüksekliğini ölçmek', 'Pervane yerine itki üretmek'], 'Su altı kanatları uçak kanadı gibi kaldırma kuvveti üretir; gövde sudan çıkınca ıslak yüzey ve direnç büyük ölçüde azalır.'),
  ('Yolcu vagonlarının ve lokomotiflerin altında, gövdeye bir pivotla bağlanan ve iki ya da üç dingili taşıyan döner tekerlek takımına ne ad verilir?', 'Boji', ['Pantograf', 'Makas', 'Kremayer'], 'Boji gövdeye göre dönebildiği için uzun vagonların kurplarda raya uyum sağlamasını kolaylaştırır; ayrıca süspansiyon elemanlarını da taşır.'),
  ('Demiryolu sinyalizasyonundaki \'blok sistemi\' hangi ilkeye dayanır?', 'Hat bölümlere ayrılır ve her bölümde aynı anda yalnız bir tren bulunabilir', ['Trenler birbirine kenetlenerek uzun ve tek bir dizi hâlinde ilerler', 'Her istasyonda bütün trenler aynı anda durdurulur', 'Sinyaller yalnız gece saatlerinde kullanılır'], 'Treni durdurmak için gereken mesafe çok uzun olduğundan sürücü öndeki treni görerek duramaz; blok sistemi trenler arasında her zaman güvenli bir boş bölüm bırakır.'),
  ('Aynı yükü taşırken demiryolu taşımacılığının karayoluna göre çok daha az enerji harcamasının temel mekanik nedeni nedir?', 'Çelik tekerlek ile çelik ray arasındaki yuvarlanma direncinin çok düşük olması', ['Trenlerin her zaman hafif yokuş aşağı eğimli hatlarda gitmesi', 'Raylarda hava direncinin bulunmaması', 'Lokomotiflerin yakıt kullanmaması'], 'Sert çelik yüzeyler temas noktasında çok az şekil değiştirir; bu yüzden lastik tekerleğe göre yuvarlanma kaybı birkaç kat küçüktür.'),
  ('Çok dik dağ yamaçlarına tırmanan bazı demiryollarında iki rayın ortasına dişli bir ray döşenir ve lokomotifin dişli çarkı bu raya geçer. Bu çözüm hangi sorunu giderir?', 'Düz tekerleğin dik eğimde patinaj yapmasını', ['Rayların ısıyla genleşip eğrilmesini', 'Kurplarda tekerleklerin raydan çıkmasını', 'Tünellerdeki havalandırma eksikliğini'], 'Düz tekerlek ile ray arasındaki tutunma belirli bir eğimin üstünde yetersiz kalır. Kremayerli sistemde çekiş sürtünmeye değil dişlilerin kavramasına dayandığından çok dik eğimler aşılabilir.'),
  ('İstanbul\'da Karaköy ile Beyoğlu arasında 1875\'ten beri çalışan Tünel hattı hangi tür raylı sistemdir?', 'Halatla çekilen füniküler', ['Manyetik levitasyonlu tren', 'Kremayerli dağ treni', 'Monoray'], 'Tünel, dik bir yokuşu çıkan ve halatla çekilen iki vagonlu bir fünikülerdir; dünyanın en eski yeraltı raylı hatlarından biri olarak bilinir.'),
  ('Lokomotiflerde sürücünün belirli aralıklarla bir pedala basmasını ya da düğmeye dokunmasını gerektiren \'ölü adam\' düzeneğinin amacı nedir?', 'Sürücü bilincini yitirirse treni kendiliğinden durdurmak', ['Sürücünün mola süresini kaydetmek', 'Yakıt tüketimini en aza indirmek', 'Motorun aşırı ısınmasını önlemek'], 'Sürücü belirli süre içinde tepki vermezse sistem önce uyarı verir, sonra frenleri otomatik devreye sokar; bu bir arızada güvenli tasarım örneğidir.'),
  ('Bir demiryolu hattının eğimi binde 25 (25 ‰) olarak verilmiştir. Bu eğimde 4 km\'lik hat boyunca tren kaç metre yükselir?', '100 m', ['25 m', '40 m', '1000 m'], 'Binde 25 eğim her 1000 m\'de 25 m yükselme demektir: 4000 × 25/1000 = 100 m.'),
  ('Güneş panellerinin yaz günlerinde çok ısındığında ürettiği güç nasıl etkilenir?', 'Hücre sıcaklığı arttıkça verim ve güç düşer', ['Sıcaklık arttıkça güç sürekli artar', 'Sıcaklığın güce hiçbir etkisi yoktur', 'Panel yalnız 50 °C\'nin üstünde çalışmaya başlar'], 'Silisyum hücrelerin gerilimi sıcaklık yükseldikçe azalır; bu nedenle aynı ışınımda serin ve güneşli bir gün, sıcak bir günden daha fazla güç verebilir.'),
  ('Güneş enerjisi sistemlerinde invertör ya da şarj denetleyicisi içindeki \'MPPT\' işlevi ne yapar?', 'Panelden en yüksek gücün alındığı çalışma noktasını sürekli izler', ['Paneli gün boyunca Güneş\'e doğru mekanik olarak döndürüp izler', 'Gece boyunca panelden elektrik üretir', 'Panel yüzeyini otomatik olarak temizler'], 'Panelin akım-gerilim eğrisinde gücün en büyük olduğu nokta ışınım ve sıcaklıkla değişir. Maksimum güç noktası izleyici yükü bu noktada tutacak biçimde gerilimi ayarlar.'),
  ('Sabit kurulan güneş panellerinde yıllık toplam üretim için önerilen eğim açısı yaklaşık olarak hangi büyüklüğe yakın seçilir?', 'Kurulum yerinin enlem açısına', ['Her yerde tam 90 dereceye', 'Her yerde sıfır dereceye', 'Panelin kendi verimine'], 'Panelin Güneş ışınlarını yıl boyunca dik yakın açıyla alması için eğimin yerin enlemine yakın olması iyi bir başlangıçtır; kesin değer iklim ve yere göre biraz değişir.'),
  ('Yoğunlaştırılmış güneş enerjisi (CSP) santralleri fotovoltaik santrallerden hangi yönüyle ayrılır?', 'Aynalarla odaklanan ışığın ısısıyla buhar üretip türbin çevirirler', ['Elektriği doğrudan yarı iletken hücrelerde fotonlarla üretmeleri', 'Yalnız geceleri çalışırlar', 'Güneş yerine rüzgârdan yararlanırlar'], 'CSP\'de geniş ayna alanları ışığı bir alıcıya odaklar; ısınan akışkanla buhar elde edilir ve klasik bir türbin-jeneratör düzeneği çalıştırılır. Isı depolanarak gece üretim de yapılabilir.'),
  ('Alanı 1,6 m² olan bir güneş paneline 1000 W/m² ışınım düşmektedir. Panel verimi %20 ise elde edilen elektrik gücü kaç watttır?', '320 W', ['200 W', '160 W', '1600 W'], 'Gelen güç 1,6 × 1000 = 1600 W\'tır; bunun %20\'si 1600 × 0,20 = 320 W eder.'),
  ('Modern rüzgâr türbinlerinde fırtına gibi çok yüksek rüzgâr hızlarında türbinin korunması için başvurulan yöntem hangisidir?', 'Kanat açısını değiştirip rotoru yavaşlatmak ya da durdurmak', ['Kanatları daha da hızlı döndürmek', 'Kuleyi yere yatırmak', 'Jeneratörü şebekeden ayırıp rotoru serbest bırakmak'], 'Kanat hatve (pitch) denetimiyle kanatlar rüzgâra kenarlarını verecek biçimde döndürülür; kaldırma azalır, rotor yavaşlar ve fren devreye girer.'),
  ('Bir PLC çalışırken sürekli tekrarlanan tarama çevriminin doğru sırası hangisidir?', 'Girişleri oku, programı yürüt, çıkışları güncelle', ['Çıkışları güncelle, girişleri oku, programı sil', 'Programı yürüt, girişleri hiç okumadan çıkışları kapat', 'Yalnız açılışta bir kez girişleri okuyup sonsuza dek bekle'], 'PLC her taramada önce bütün girişlerin anlık durumunu belleğe alır, ardından programı bu görüntüye göre işler ve en sonunda çıkışları topluca yazar.'),
  ('PLC programlamada yaygın olan merdiven (ladder) diyagramı adını ve biçimini nereden alır?', 'Elektrikçilerin alışık olduğu röle kumanda şemalarından', ['Binalardaki yangın merdivenlerinin mimari kesit çizimlerinden', 'Akış şemalarındaki karar kutularından', 'Matematikteki basamak fonksiyonlarından'], 'İki dikey besleme hattı arasına yatay basamaklar hâlinde kontak ve bobin sembolleri çizilir; bu, röle mantığını bilen teknisyenlerin programı kolayca okumasını sağlar.'),
  ('Bir kentin içme suyu depolarının, pompa istasyonlarının ve vanalarının tek bir merkezden uzaktan izlenip denetlendiği sisteme ne ad verilir?', 'SCADA', ['CAD', 'PLC\'siz röle panosu', 'Ladder diyagramı'], 'SCADA (denetleyici kontrol ve veri toplama) geniş bir alana yayılmış saha cihazlarından veri toplar, alarm üretir ve operatöre uzaktan komut verme olanağı sunar.'),
  ('Bir konveyörde metal kutular ile plastik kutular aynı hatta ilerliyor. Yalnız metal kutuları temassız algılamak için en uygun sensör hangisidir?', 'Endüktif yakınlık sensörü', ['Kapasitif yakınlık sensörü', 'Termokupl', 'Mikrofon tipi ses sensörü'], 'Endüktif sensör ürettiği değişken manyetik alanda metalde oluşan girdap akımlarını algılar; plastiğe tepki vermez. Kapasitif sensör ise plastik ve sıvıları da algılayabilir.'),
  ('0–100 °C aralığını 4–20 mA çıkışa doğrusal olarak çeviren bir sıcaklık vericisi 12 mA gösteriyor. Ölçülen sıcaklık kaç derecedir?', '50 °C', ['60 °C', '12 °C', '37,5 °C'], '16 mA\'lik aralıkta 12 mA, alt değerin 8 mA üstündedir: 8/16 = 0,5 ve 0,5 × 100 = 50 °C.'),
  ('Bir sorunun olası nedenlerini insan, makine, malzeme, yöntem gibi ana başlıklar altında, ortadaki bir ok gövdesine bağlanan dallar hâlinde gösteren araç hangisidir?', 'Ishikawa (balık kılçığı) diyagramı', ['Gantt şeması', 'Histogram', 'Dağılım diyagramı'], 'Kaoru Ishikawa\'nın geliştirdiği neden-sonuç diyagramında sonuç balığın başına yazılır; olası nedenler kılçıklar gibi kategorilere ayrılarak beyin fırtınasına çerçeve sağlar.'),
  ('İşyeri düzenini sağlayan 5S yönteminin ilk adımı olan \'Seiri\' neyi gerektirir?', 'Gereksiz eşyaları ayıklayıp çalışma alanından çıkarmayı', ['Bütün alanı boyayıp yeniden döşemeyi', 'Çalışma alanını her gün temizlemeyi', 'Her aleti etiketleyip yerini belirlemeyi'], '5S sırasıyla ayıkla, düzenle, temizle, standartlaştır ve sürdür adımlarından oluşur; ilk adımda yalnız gerçekten gerekenler alanda bırakılır.'),
  ('\'Tam zamanında\' (just-in-time) üretim anlayışının temel hedefi nedir?', 'Parçaların tam gerektiği anda gelmesiyle stokları en aza indirmek', ['Depoları her zaman sonuna kadar dolu tutarak her talebe hemen yanıt vermek', 'Bütün parçaları yıllar önceden sipariş etmek', 'Üretimi yalnız gece vardiyasında yapmak'], 'Stok, para bağlar ve sorunları gizler. Tam zamanında üretimde malzeme akışı talebe göre ayarlanır; ancak tedarik zincirindeki aksaklıklara karşı daha duyarlı bir sistem ortaya çıkar.'),
  ('Bazı otomobil fabrikalarında her işçinin bir hata gördüğünde ipi çekerek hattı durdurabilmesine izin verilir. Bu uygulamanın kalite açısından gerekçesi nedir?', 'Hatayı kaynağında yakalayıp kusurlu parçaların ilerlemesini önlemek', ['İşçilerin daha uzun mola vermesini sağlamak', 'Üretim hızını her koşulda en yükseğe çıkarıp vardiya hedefini aşmak', 'Hata kayıtlarını tamamen ortadan kaldırmak'], 'Andon ipi çekilince ışıklı uyarı yanar ve ekip sorunu hemen çözer. Kısa duruşlar, hatanın yüzlerce araca yayılmasından çok daha ucuzdur.'),
  ('Yalın üretimde \'israf\' (muda) sayılmayan etkinlik hangisidir?', 'Müşterinin parasını ödediği bir parçanın montajını yapmak', ['Siparişten fazla ürün üretip satılana kadar depoda bekletmek', 'Parçaları gereksiz yere fabrika içinde taşımak', 'Bir önceki istasyonun işini bitirmesini boşta beklemek'], 'Fazla üretim, gereksiz taşıma ve bekleme yalın üretimdeki klasik israf türlerindendir. Ürüne müşterinin değer verdiği bir dönüşüm katan montaj ise değer yaratan iştir.'),
  ('1856\'da patentlenen ve erimiş pik demirin içinden hava üflenerek fazla karbonun yakılmasıyla ucuz ve bol çelik üretimini başlatan yöntem kimin adıyla anılır?', 'Henry Bessemer', ['Isambard Kingdom Brunel', 'Abraham Darby', 'Thomas Telford'], 'Bessemer konvertöründe üflenen havadaki oksijen karbon ve safsızlıkları yakar; çeliğin fiyatı büyük ölçüde düştü ve demiryolu, köprü ve gemi yapımı hızlandı.'),
  ('Trenlerde lokomotiften kumanda edilen basınçlı havalı fren sistemini 1869\'da geliştirerek demiryolu güvenliğini büyük ölçüde artıran mucit kimdir?', 'George Westinghouse', ['George Stephenson', 'Thomas Edison', 'Alexander Graham Bell'], 'Westinghouse\'un hava freni sayesinde bütün vagonlar aynı anda frenlenebildi; daha sonraki biçimi hava basıncı düşünce frenleri kendiliğinden devreye sokacak biçimde geliştirildi.'),
  ('Dicle Nehri üzerinde yapılan ve göl alanı nedeniyle tarihî Hasankeyf kentinin büyük kısmının sular altında kalmasına yol açan baraj hangisidir?', 'Ilısu Barajı', ['Keban Barajı', 'Atatürk Barajı', 'Deriner Barajı'], 'Ilısu Barajı Mardin ile Şırnak sınırında yer alır. Göl suları yükselmeden önce Hasankeyf\'teki bazı tarihî yapılar yeni bir alana taşınmıştır.'),
  ('Vecihi Hürkuş\'un 1925\'te İzmir\'de kısıtlı olanaklarla tasarlayıp yaptığı Vecihi K-VI uçağı hangi özelliğiyle bilinir?', 'Türkiye\'de tasarlanıp üretilen ilk uçak olması', ['Dünyanın ilk jet motorlu uçağı olması', 'Türkiye\'nin ilk yolcu uçağı olarak seferlere başlaması', 'Okyanusu aktarmasız geçen ilk uçak olması'], 'Vecihi K-VI, hurdaya ayrılmış uçak parçalarından ve yerli malzemeden yapılmış, Türk mühendisliğinin ilk özgün uçak tasarımı sayılır.'),
  ('\'Çin Seddi uzaydan çıplak gözle görülebilen tek insan yapısıdır\' yaygın inanışı için hangisi doğrudur?', 'Yanlıştır; set çok dar olduğundan yörüngeden bile çıplak gözle seçilemez', ['Doğrudur; Ay\'dan bile kolayca görülebildiği astronotlarca defalarca doğrulanmıştır', 'Doğrudur; çünkü uzunluğu Dünya\'nın çevresine eşittir', 'Yalnız gece aydınlatıldığı için doğrudur'], 'Setin genişliği çoğunlukla birkaç metredir ve rengi çevresindeki araziye benzer. Astronotların aktarımları, alçak yörüngeden bile çıplak gözle seçilmesinin çok zor olduğunu gösterir.'),
  ('Osaka Körfezi\'nde yapay bir ada üzerine kurulan Kansai Uluslararası Havalimanı\'nın açıldığı günden beri karşılaştığı temel mühendislik sorunu nedir?', 'Deniz tabanındaki yumuşak kil katmanlarının oturması', ['Pistlerin aşırı rüzgârla aşınması', 'Adanın tektonik hareketle her yıl birkaç metre kuzeye doğru kayması', 'Terminal çatısının güneşte erimesi'], 'Ada, sıkışabilir deniz kili üzerine dolguyla oluşturuldu. Kil yük altında suyunu verdikçe ada metrelerce oturdu; binalarda kolon boyları ayarlanabilir biçimde tasarlandı.'),
  ('Japonya\'nın Honşu ve Hokkaido adalarını deniz tabanının altından demiryoluyla birbirine bağlayan ve yaklaşık 54 km uzunluğundaki tünel hangisidir?', 'Seikan Tüneli', ['Manş Tüneli', 'Gotthard Ana Tüneli', 'Lötschberg Tüneli'], '1988\'de açılan Seikan Tüneli\'nin yaklaşık 23 km\'lik kısmı Tsugaru Boğazı\'nın altından geçer; uzun yıllar dünyanın en uzun demiryolu tüneli olmuştur.'),
  ('Katener benzeri bir eğri biçiminde yapılan, paslanmaz çelik kaplı ve yaklaşık 192 m yüksekliğindeki \'Gateway Arch\' hangi şehirdedir?', 'St. Louis', ['Chicago', 'San Francisco', 'New York'], '1965\'te tamamlanan Gateway Arch, Mississippi Nehri kıyısında Amerika\'nın batıya açılışını simgeler; biçimi kendi ağırlığını büyük ölçüde basınçla taşıyacak şekilde seçilmiştir.'),
  ('1958 Brüksel Dünya Fuarı için yapılan Atomium neyi temsil eder?', 'Bir demir kristalinin birim hücresinin dev boyutlu modelini', ['Güneş sistemindeki gezegenlerin dizilişini', 'Bir DNA molekülünün sarmalını', 'Avrupa\'nın başkentlerini birbirine bağlayan otoyol ağının küçük bir maketini'], 'Atomium dokuz küreden oluşur; küreler, hacim merkezli kübik demir kafesindeki atomları, aradaki borular da bağları simgeler.'),
  ('Londra\'daki dev dönme dolap London Eye\'ın dış çemberi ile göbeği arasında gergin çelik kablolar bulunur. Bu yapı hangi tanıdık nesnenin çalışma ilkesine benzer?', 'Telli bisiklet tekerleği', ['Kemerli taş köprü', 'Asılı zincir', 'Rüzgârda açılan katlanır şemsiye'], 'Bisiklet tekerleğindeki gibi ön gerilmeli ince teller, dış çemberi göbeğe bağlar ve büyük çapta hafif ama rijit bir çark elde edilmesini sağlar.'),
  ('Nil üzerindeki Asvan Yüksek Barajı taşkınları denetlemiş ve elektrik üretmiştir. Barajın tarımla ilgili önemli bir olumsuz sonucu hangisidir?', 'Taşkınların getirdiği bereketli milin tarlalara ulaşmaması', ['Mısır\'daki bütün tarım arazilerinin kurumasına yol açması', 'Nil\'in akış yönünün tersine dönmesi', 'Baraj gölünün buharlaşmayla tamamen tuzlu bir iç denize dönüşmesi'], 'Eskiden her yıl taşkınla gelen alüvyon tarlaları doğal olarak gübreliyordu. Mil artık baraj gölünde çökeldiğinden yapay gübre ihtiyacı arttı ve deltada kıyı aşınması hızlandı.'),
  ('Bir inşaat alanında iki nokta arasındaki yükseklik farkını bulmak için yatay bakış çizgisi oluşturan nivo ve dik tutulan bölümlü mira ile yapılan ölçme işlemine ne ad verilir?', 'Nivelman', ['Triangülasyon', 'Poligon ölçümü', 'Aplikasyon'], 'Nivelmanda nivo yatay bir bakış düzlemi oluşturur; iki noktadaki miradan okunan değerlerin farkı, noktalar arasındaki yükseklik farkını verir.'),
  ('Bir nivelman ölçümünde A noktasındaki miradan 1,85 m, B noktasındaki miradan 0,60 m okunuyor. B noktası A\'ya göre nasıldır?', '1,25 m daha yüksektir', ['1,25 m daha alçaktır', '0,60 m daha alçak kalmaktadır', '0,60 m daha alçaktır'], 'Bakış çizgisi yataydır; mirada daha küçük değer okunan nokta bu çizgiye daha yakındır, yani daha yüksektir. Fark 1,85 − 0,60 = 1,25 m\'dir.'),
  ('Bir GNSS (örneğin GPS) alıcısının enlem, boylam ve yüksekliği bulabilmesi için en az kaç uydudan sinyal alması gerekir?', '4', ['2', '3', '12'], 'Üç bilinmeyen konum bileşenine ek olarak alıcı saatinin hatası da bilinmeyendir; dört bilinmeyenli çözüm için en az dört uydudan uzaklık ölçümü gerekir.'),
  ('Bir yolun proje çalışmalarında yüksekliği kesin olarak bilinen ve bütün kot ölçümlerinin bağlandığı sabit işaret noktasına ne ad verilir?', 'Röper (reper) noktası', ['Kilit taşı', 'Durak noktası', 'Kesişim noktası'], 'Röperler kalıcı biçimde zemine ya da yapılara sabitlenir; yeni ölçümler bu noktalardan başlatılarak bütün projede aynı yükseklik sistemi kullanılır.'),
  ('Projede koordinatları belli olan bina köşelerinin ve kazık yerlerinin ölçme aletleriyle araziye işaretlenmesine ne ad verilir?', 'Aplikasyon', ['Nivelman', 'Kalibrasyon', 'Enterpolasyon'], 'Aplikasyon, kâğıt ya da bilgisayardaki tasarımı araziye aktarma işlemidir; hatalı aplikasyon yapının komşu parsele taşması gibi ciddi sorunlara yol açabilir.'),
  ('Bir mikrodenetleyicinin girişine bağlı düğme basılı değilken girişin belirsiz (havada) kalmaması için giriş ile besleme arasına bir direnç konur. Bu dirence ne ad verilir?', 'Pull-up (yukarı çekme) direnci', ['Sönümleme (snubber) direnci', 'Akım şönt direnci', 'Isıtıcı direnç'], 'Bağlantısız bir giriş çevredeki gürültüyü toplayıp rastgele 0 ya da 1 okunabilir. Pull-up direnci girişi düğme basılmadığında kararlı biçimde 1 düzeyinde tutar; düğmeye basınca giriş toprağa çekilir.'),
  ('Mekanik bir düğmeye tek kez basıldığı hâlde mikrodenetleyici birkaç basma algılıyor. Bu sorunun nedeni ve yaygın çözümü hangisidir?', 'Kontakların kısa süre sıçraması; yazılım ya da RC ile gecikmeli okuma', ['Düğmenin çok büyük akım çekmesi; bu yüzden daha kalın kablo kullanılmalıdır', 'Mikrodenetleyicinin çok yavaş olması; saat frekansını düşürme', 'Toprak hattının kopması; düğmeyi ters bağlama'], 'Metal kontaklar kapanırken birkaç milisaniye titreşip açılıp kapanır. Okumayı bu süre kadar bekletmek ya da küçük bir RC filtre kullanmak tek basmanın tek kez algılanmasını sağlar.'),
  ('Dört anahtarın çapraz çiftler hâlinde açılıp kapanmasıyla bir DC motorun dönüş yönünü elektronik olarak değiştiren sürücü devresine ne ad verilir?', 'H köprüsü', ['Wheatstone köprüsü', 'Tam dalga doğrultucu', 'Gerilim bölücü'], 'Motor, harf biçimindeki devrenin ortasındaki yatay çizgide durur. Bir çapraz çift iletimdeyken akım motordan bir yönde, öteki çift iletimdeyken ters yönde geçer.'),
  ('Akıllı telefonlardaki kapasitif dokunmatik ekranların çoğunun kalın kumaş eldivenle kullanılamamasının nedeni nedir?', 'Ekran parmağın oluşturduğu kapasitans değişimini algılar; eldiven bunu engeller', ['Ekranın dokunuşu yalnız basınçla algılaması ve kalın eldivenin bu basıncı dağıtması', 'Eldivenin ekrana statik elektrik yükleyip ekranı kilitlemesi', 'Ekranın yalnız vücut sıcaklığını algılaması'], 'Kapasitif ekranda yüzeydeki elektrot ızgarası bir elektrik alanı oluşturur. İletken parmak bu alanı bozarak dokunulan noktadaki kapasitansı değiştirir; yalıtkan eldiven bu bağlantıyı keser.'),
  ('Gömülü sistemlerde yazılım bir döngüde takılıp kalırsa mikrodenetleyiciyi kendiliğinden yeniden başlatan donanım zamanlayıcısına ne ad verilir?', 'Bekçi köpeği zamanlayıcısı', ['Gerçek zaman saati (RTC) modülü', 'Kesme denetleyicisi', 'Darbe genişlik modülatörü'], 'Program olağan çalışırken bu zamanlayıcıyı düzenli aralıklarla sıfırlar. Program kilitlenip sıfırlama yapamazsa zamanlayıcı dolar ve sistemi baştan başlatır.'),
  ('1961\'de General Motors fabrikasında sıcak döküm parçalarını taşımak için çalışmaya başlayan ve ilk endüstriyel robot sayılan makine hangisidir?', 'Unimate', ['ASIMO', 'Shakey', 'Sojourner'], 'George Devol ile Joseph Engelberger\'in geliştirdiği Unimate, programlanabilir hidrolik bir koldu; tehlikeli ve tekrarlı işleri insanlardan devraldı.'),
  ('Üç birbirine dik doğrusal eksende (x, y, z) hareket eden ve çoğu 3B yazıcı ile CNC tezgâhında görülen robot yapısına ne ad verilir?', 'Kartezyen (portal) robot', ['Küresel robot', 'Paralel (delta) robot', 'İnsansı (iki ayaklı) robot'], 'Kartezyen robotlarda her eksen ayrı bir doğrusal kızakla sürülür; konum hesabı basittir ve geniş, dikdörtgen bir çalışma alanı elde edilir.'),
  ('İşbirlikçi robotları (cobot) klasik endüstriyel robotlardan ayıran temel özellik nedir?', 'Kafes olmadan insanlarla aynı alanda güvenle çalışacak biçimde tasarlanmaları', ['Her zaman insanlardan çok daha hızlı, güçlü ve ağır yük taşıyabilir olmaları', 'Yalnız uzay istasyonlarında kullanılmaları', 'Hiçbir algılayıcı taşımamaları'], 'Cobotlar kuvvet ve hız sınırlaması, çarpışma algılama ve yumuşak yüzeylerle tasarlanır; bir insana değdiklerinde durarak yaralanma riskini azaltırlar.'),
  ('Kendi kendini dengeleyen iki tekerlekli bir robot ya da dört pervaneli bir drone, eğim açısını ve dönme hızını sürekli olarak hangi algılayıcı ikilisiyle ölçer?', 'İvmeölçer ve jiroskop', ['Termometre ve higrometre', 'Mikrofon ve hoparlör', 'Barometre ve pusula iğnesi'], 'İvmeölçer yerçekimi yönünü, jiroskop ise açısal hızı ölçer. İkisinin verisi birleştirilerek (eylemsizlik ölçüm birimi) denetleyici eğimi doğru ve hızlı biçimde hesaplar.'),
  ('Mars\'taki keşif araçlarının Dünya\'dan bir oyuncak araba gibi anlık olarak sürülememesinin temel nedeni nedir?', 'Radyo sinyallerinin gidiş-dönüşünün dakikalar sürmesi', ['Mars\'ın ince atmosferinde elektrik akımının kablolarla iletilememesi', 'Araçların hiç kamera taşımaması', 'Mars yüzeyinin tamamen buzla kaplı olması'], 'Işık hızıyla bile tek yönlü iletişim Dünya-Mars uzaklığına göre birkaç dakikadan yirmi dakikayı aşan sürelere ulaşır. Bu yüzden araçlara hedef verilir, engellerden kaçınmayı kendileri yapar.'),
  ('Aktif çamur yöntemiyle biyolojik arıtma yapılan havuzlara sürekli hava üflenmesinin nedeni nedir?', 'Organik maddeyi ayrıştıran mikroorganizmalara oksijen sağlamak', ['Suyu soğutup havuz yüzeyindeki buharlaşmayı en aza indirerek su kaybını önlemek', 'Havuzdaki çamuru dibe bastırıp sıkıştırmak', 'Suya karbondioksit verip asitliğini artırmak'], 'Oksijenli ortamda çoğalan bakteriler atık sudaki organik kirleticileri besin olarak kullanıp karbondioksit ve suya dönüştürür; oluşan bakteri kütlesi sonra çöktürülür.'),
  ('Su kirliliği raporlarında sıkça geçen BOİ (biyokimyasal oksijen ihtiyacı) değerinin yüksek olması neyi gösterir?', 'Suda mikroorganizmalarca ayrıştırılacak çok organik madde olduğunu', ['Suyun içme suyu olarak çok temiz olduğunu', 'Suda hiç canlı yaşamadığını ve kirliliğin sıfır olduğunu', 'Suyun tuzluluğunun deniz suyundan fazla olduğunu'], 'BOİ, organik maddelerin bakterilerce ayrıştırılması için gereken oksijen miktarıdır. Yüksek BOİ\'li atık su akarsuya verilirse sudaki çözünmüş oksijeni tüketip balık ölümlerine yol açabilir.'),
  ('Deniz suyundan içme suyu elde eden tesislerin çoğunda kullanılan ters ozmoz yöntemi nasıl çalışır?', 'Su yüksek basınçla tuzu geçirmeyen yarı geçirgen bir zardan geçirilir', ['Su güneşte bekletilip üstteki tatlı katman alınır', 'Suya şap eklenerek tuz tortu hâlinde çöktürülür', 'Su donduruluyor ve tuzlu buz atılıyor'], 'Doğal ozmozda su az tuzlu taraftan çok tuzlu tarafa geçer. Tuzlu tarafa ozmotik basıncı aşan bir basınç uygulanınca su ters yönde, zardan tatlı su olarak süzülür.'),
  ('Modern bir düzenli çöp depolama sahasının tabanına sıkıştırılmış kil ve plastik geomembran serilmesinin amacı nedir?', 'Çöp sızıntı suyunun yeraltı suyuna karışmasını önlemek', ['Çöplerin daha hızlı çürüyüp birkaç hafta içinde tamamen yok olmasını sağlamak', 'Sahaya yağmur yağmasını engellemek', 'Kuşların ve hayvanların sahaya girmesini önlemek'], 'Atıklardan süzülen kirli sızıntı suyu ağır metal ve organik kirletici taşır. Geçirimsiz taban bu suyu tutar; drenaj borularıyla toplanıp arıtmaya gönderilir.'),
  ('Büyük çöp depolama sahalarında atıkların içine dikey borular yerleştirilip gaz toplanması hangi amaçlara hizmet eder?', 'Patlama riskini azaltmak ve metandan enerji üretmek', ['Çöpleri soğutup donmalarını sağlamak', 'Sahayı daha hızlı doldurmak için çöpleri sıkıştırmak', 'Oksijen üretip çevredeki havayı temizlemek'], 'Oksijensiz ortamda çürüyen organik atıklar metan ve karbondioksit üretir. Toplanmayan metan birikip patlayabilir ve güçlü bir sera gazıdır; toplanan gaz yakılarak elektrik üretilebilir.'),
  ('Termik santral bacalarında elektrostatik filtreler toz parçacıklarını gazdan nasıl ayırır?', 'Parçacıkları elektrikle yükleyip zıt yüklü plakalarda toplayarak', ['Parçacıkları suda çözüp sıvı olarak bacadan atarak', 'Gazı çok ince bir elekten bastırıp parçacıkları ezerek', 'Parçacıkları yakıp tamamen gaz hâline getirerek'], 'Yüksek gerilimli elektrotlar gazı iyonlaştırır; toza yapışan yükler parçacıkları topraklı plakalara çeker. Plakalar düzenli silkelenerek toplanan kül alınır.'),
  ('Binalardaki otomatik yağmurlama (sprinkler) başlıklarının çoğu yangın çıktığında nasıl açılır?', 'Isınan başlıktaki sıvı dolu cam ampulün patlamasıyla yalnız o başlık açılır', ['Bir alarm çalınca binadaki bütün başlıklar aynı anda açılır', 'Görevli bir düğmeye basınca suyu elle verir', 'Başlıklar dumanı görünce kamera yardımıyla açılır'], 'Ampuldeki sıvı belirli bir sıcaklıkta genleşip camı kırar ve tıpa açılır. Yalnız yangının üstündeki birkaç başlık çalıştığından su hasarı sınırlı kalır.'),
  ('Evlerde ve otellerde yaygın kullanılan optik duman dedektörleri dumanı nasıl algılar?', 'Duman parçacıklarının odacıktaki ışığı saçıp algılayıcıya ulaştırmasıyla', ['Ortam sıcaklığının 100 °C\'yi geçmesiyle', 'Dumandaki karbonun elektrik iletmesiyle', 'Dumanın kokusunu kimyasal bir dille tatmasıyla'], 'Karanlık bir odacıkta ışık kaynağı algılayıcıya doğrudan bakmaz. İçeri giren duman parçacıkları ışığı saçınca bir kısmı algılayıcıya ulaşır ve alarm tetiklenir.'),
  ('Üzerinde \'ABC\' yazan kuru kimyevi tozlu yangın söndürücüsü hangi yangın türlerinde kullanılabilir?', 'Katı maddeler, yanıcı sıvılar ve yanıcı gazlarda', ['Yalnız metal yangınlarında', 'Yalnız mutfaktaki yemek yağı yangınlarında', 'Yalnız kâğıt, ahşap ve kumaş gibi katı madde yangınlarında'], 'A sınıfı ahşap, kâğıt, kumaş gibi katıları; B sınıfı benzin, boya gibi sıvıları; C sınıfı ise doğal gaz, propan gibi gazları kapsar. Metal yangınları için özel söndürücüler gerekir.'),
  ('2017\'de Londra\'daki Grenfell Kulesi yangınında alevlerin dış cephe boyunca çok hızlı yükselmesinin temel nedeni olarak gösterilen etken hangisidir?', 'Cepheye sonradan yapılan yanıcı çekirdekli kaplama panelleri', ['Binanın bütünüyle ahşap taşıyıcı sistemle ve ahşap döşemelerle yapılmış olması', 'Yangın sırasında şiddetli bir depremin yaşanması', 'Binada hiç pencere bulunmaması'], 'Yenileme sırasında yalıtımla birlikte takılan, polietilen çekirdekli alüminyum kompozit paneller alevi cephe boyunca bir baca gibi taşıdı. Olay cephe malzemelerinin yangın davranışı kurallarının sıkılaştırılmasına yol açtı.'),
  ('Bir asansörün kabin kütlesi 1000 kg, anma yükü 800 kg\'dır. Karşı ağırlık yaygın uygulamaya göre kabin kütlesine anma yükünün yarısı eklenerek seçilirse karşı ağırlık kaç kilogram olur?', '1400 kg', ['1800 kg', '900 kg', '1000 kg'], 'Karşı ağırlık = 1000 + 0,5 × 800 = 1400 kg. Böylece kabin yarı doluyken iki taraf dengededir ve motor en az zorlanır.'),
  ('Çok yüksek gökdelenlerde bütün asansörlerin zemin kattan en üst kata kadar her katta durması yerine asansörlerin kat gruplarına (bölgelere) ayrılmasının temel nedeni nedir?', 'Bekleme sürelerini kısaltıp asansör kuyularının kapladığı alanı azaltmak', ['Asansörlerin yalnız gece saatlerinde ve yalnız yük taşımak amacıyla çalışmasını sağlamak', 'Halat uzunluğunu sıfıra indirmek', 'Bütün yolcuların aynı kabine binmesini sağlamak'], 'Her asansör yalnız kendi bölgesine hizmet edince sefer süreleri kısalır. Ayrıca üst bölgelerde alt bölge kuyuları sona erdiği için katlarda kiralanabilir alan artar.'),
  ('Kışın dışarıdan alınan soğuk hava evde ısıtıldığında içerideki havanın çok kuru hissedilmesinin nedeni nedir?', 'Isınan havanın nem tutma kapasitesi artar, bu yüzden bağıl nem düşer', ['Isıtma sırasında kaloriferin havadaki su buharını yakarak tamamen yok etmesi', 'Kalorifer peteklerinin suyu havadan emmesi', 'Soğuk havada hiç su buharı bulunmaması'], 'Havadaki su buharı miktarı aynı kalsa da sıcak hava çok daha fazla buhar tutabilir; oran olarak bağıl nem büyük ölçüde düşer. Nemlendiriciler bu yüzden kışın kullanılır.'),
  ('Isı geri kazanımlı havalandırma cihazları kışın enerji tasarrufunu nasıl sağlar?', 'Dışarı atılan ılık iç havanın ısısını içeri alınan soğuk taze havaya aktararak', ['İçerideki havayı hiç değiştirmeden filtreleyip tekrar tekrar odaya dolaştırarak', 'Taze havayı elektrikli ısıtıcıyla doğrudan yakarak ısıtarak', 'Pencereleri kendiliğinden açıp kapatarak'], 'İki hava akımı birbirine karışmadan bir ısı değiştiriciden geçer; kirli hava dışarı atılırken ısısının önemli kısmı taze havaya kalır.'),
  ('Yerden ısıtma sistemlerinde borulardaki suyun kalorifer peteklerine göre çok daha düşük sıcaklıkta tutulabilmesinin nedeni nedir?', 'Isıyı yayan yüzeyin bütün döşeme kadar geniş olması', ['Döşeme malzemesinin kendisinin ısı üretmesi', 'Suyun borularda daha hızlı akmasının onu ısıtması', 'Sıcak havanın her zaman aşağı doğru çökmesi'], 'Verilen ısı yüzey alanı ile sıcaklık farkının çarpımına bağlıdır. Çok geniş bir yüzey, küçük bir sıcaklık farkıyla bile yeterli ısıyı verir; bu da düşük sıcaklıklı ısı pompaları ve yoğuşmalı kazanlarla verimli çalışmayı sağlar.'),
  ('Kalabalık bir sınıfta havalandırma, ortamdaki karbondioksit derişimini ölçen bir algılayıcıya bağlanıyor. Bu tasarımın gerekçesi nedir?', 'CO₂ derişimi, içerideki insan sayısına göre taze hava ihtiyacının iyi bir göstergesidir', ['CO₂ algılayıcılarının yangını, ısı dedektörlerinden önce ve kesin olarak bulabilmesi', 'Karbondioksit artınca oda sıcaklığı her zaman düşer', 'Algılayıcı havadaki oksijeni artırarak havayı temizler'], 'Solunan havadaki CO₂ insan sayısı ve kalış süresiyle artar. Talep denetimli havalandırma, boş ya da az dolu saatlerde fanı kısarak enerji tasarrufu sağlar, kalabalıkta ise hava kalitesini korur.'),
  ('Hangi sıcaklık değerinde Celsius ve Fahrenheit ölçekleri aynı sayıyı gösterir?', '−40', ['0', '−32', '100'], 'F = 1,8·C + 32 denkleminde F = C alınırsa C = 1,8·C + 32, buradan −0,8·C = 32 ve C = −40 bulunur.'),
  ('Bir otomobilin kapı kenarındaki etikette lastik basıncı 32 psi olarak yazıyor. 1 bar yaklaşık 14,5 psi olduğuna göre bu basınç yaklaşık kaç bardır?', '2,2 bar', ['3,2 bar', '4,6 bar', '0,45 bar'], '32 / 14,5 ≈ 2,2 bar bulunur. Psi, inç kareye düşen pound-kuvvet olarak tanımlanan Amerikan birimidir.'),
  ('Yolcu uçakları sıklıkla 35 000 fit irtifada uçar. Bir fit 0,3048 m olduğuna göre bu irtifa yaklaşık kaç kilometredir?', '10,7 km', ['35 km', '3,5 km', '1,07 km'], '35 000 × 0,3048 = 10 668 m, yani yaklaşık 10,7 km. Havacılıkta irtifa geleneksel olarak fit cinsinden verilir.'),
  ('Bir binadaki paratoner sisteminin asıl görevi nedir?', 'Yıldırım akımına binanın dışından toprağa giden güvenli bir yol sağlamak', ['Bulutlardaki yükü tamamen yok edip yıldırımın düşmesini kesin olarak önlemek', 'Yıldırımın elektriğini depolayıp binada kullanmak', 'Binanın içindeki prizlere ek gerilim vermek'], 'Paratoner yıldırımı engellemez; düşen yıldırımın akımını yakalama ucu, iniş iletkenleri ve topraklama elektrotlarıyla yapı malzemelerinden geçirmeden toprağa iletir. Böylece yangın ve parçalanma önlenir.'),
  ('2011\'de Japonya\'daki Fukushima Daiichi nükleer santralinde reaktörlerin aşırı ısınmasına yol açan temel mühendislik zafiyeti hangisidir?', 'Tsunaminin su bastırdığı yedek jeneratörlerin soğutma pompalarını besleyememesi', ['Reaktörlerin yanlışlıkla tam güçte deneye sokulması', 'Santralin hiçbir deprem önlemi alınmadan yapılmış olması', 'Kontrol çubuklarının hiç bulunmaması'], 'Deprem anında reaktörler otomatik olarak durdu, fakat ardından gelen tsunami alçak kotta duran dizel jeneratörleri ve elektrik panolarını su altında bıraktı. Kapanmış reaktörlerdeki kalıntı ısı uzaklaştırılamadı.'),
];
